from pathlib import Path
import argparse,json
ap=argparse.ArgumentParser(); ap.add_argument('mode',choices=['fallback','custom','first-party']); ap.add_argument('--repo',default='.'); a=ap.parse_args(); repo=Path(a.repo).resolve(); p=repo/'site-management'/'release_targets.json'; d=json.loads(p.read_text(encoding='utf-8')); m={'fallback':'bookingkoala_fallback','custom':'custom_booking','first-party':'first_party_embeds'}; d['transaction_mode']=m[a.mode]; p.write_text(json.dumps(d,indent=2)+'\n',encoding='utf-8'); active=d['custom_booking_base'] if d['transaction_mode']=='custom_booking' else d['fallback_base']; print('Transaction mode:',d['transaction_mode']); print('BK target:',active); print('Commit this config change on cloudflare-staging, validate, then promote normally.')
